const LANG_CODE_MAP: Record<string, string> = {
  fr: 'French',
  French: 'French',
  es: 'Spanish',
  Spanish: 'Spanish',
  de: 'German',
  German: 'German',
  it: 'Italian',
  Italian: 'Italian',
  pt: 'Portuguese',
  Portuguese: 'Portuguese',
  ru: 'Russian',
  Russian: 'Russian',
  zh: 'Chinese',
  Chinese: 'Chinese',
  ja: 'Japanese',
  Japanese: 'Japanese',
  en: 'English',
  English: 'English',
  ar: 'Arabic',
  Arabic: 'Arabic',
  'Egyptian Ammiya': 'Egyptian Ammiya',
};

export function localize(language: string | undefined, en: string, ar?: string): string {
  if (language === 'Arabic' || language === 'Egyptian Ammiya' || language === 'ar') return ar || en;
  const langKey = language ? (LANG_CODE_MAP[language] || language) : 'English';
  if (langKey && EXTRA[langKey] && EXTRA[langKey][en]) return EXTRA[langKey][en];
  return en;
}
